+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\hwdesk\Service;
+
+use Drupal\Core\Entity\EntityTypeManagerInterface;
+use Drupal\hwdesk\AssetStatus;
+use Drupal\hwdesk\HandoverStatus;
+
+/**
+ * Provides statistics for the dashboard overview.
+ */
+final class DashboardStats {
+  public function __construct(
+    private readonly EntityTypeManagerInterface $entityTypeManager,
+  ) {}
+
+  /**
+   * Counts assets by status in the order defined by AssetStatus::cases().
+   */
+  public function byStatus(): array {
+    $result = [];
+    foreach (AssetStatus::cases() as $case) {
+      $result[$case->value] = 0;
+    }
+    $storage = $this->entityTypeManager->getStorage('hwdesk_asset');
+    foreach (array_keys($result) as $status) {
+      $count = $storage->getQuery()
+        ->accessCheck(FALSE)
+        ->condition('status', $status)
+        ->count()
+        ->execute();
+      $result[$status] = (int) $count;
+    }
+    return $result;
+  }
+
+  /**
+   * Counts assets by type, only types that occur.
+   */
+  public function byType(): array {
+    $query = $this->entityTypeManager->getStorage('hwdesk_asset')->getAggregateQuery();
+    $query->accessCheck(FALSE)
+      ->groupBy('type')
+      ->aggregate('id', 'COUNT');
+    $rows = $query->execute();
+    $counts = [];
+    foreach ($rows as $row) {
+      /** @var \stdClass $row */
+      $type = (string) ($row->type ?? '');
+      $cnt = (int) ($row->COUNT ?? 0);
+      if ($type !== '') {
+        $counts[$type] = $cnt;
+      }
+    }
+    if (!$counts) {
+      return [];
+    }
+    // Sort by count descending then type ascending.
